mapper.select:
select ifnull(count(1),0) from ( SELECT rtp.REPORT_CODE reportCode, rtp.TYPE_DETAIL typeDetail, rtp.SUBMIT_REQUIRE submitRequire, rtp.SUBMIT_POINT_BOND submitPointBond, rtp.SUBMIT_POINT_BANK submitPointBank, rtp.STATUS status, rtp.WORKFLOW_ID workflowId, rtp.UPDATE_USER updateUser, rtp.UPDATE_TIME updateTime FROM CHB_REG_TIME_POINTS rtp WHERE STATUS = 'E' AND ORG_CODE = #{orgCode}
AND REPORT_CODE LIKE concat_ws('',concat_ws('','%',#{reportCode}),'%')
)
